-- Lernfeld:1 > Das Unternehmen und die eigene Rolle im Betrieb beschreiben > Rechtliches > Gesetze > Bürgerliches Gesetzbuch
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann das BGB meinen Ausbildungsvertrag regeln?', 2, '[{"text": "Ja", "correct": true, "because": "Allgemeine Vertragsregeln"}, {"text": "Nein", "correct": false, "because": "BBiG ergänzt, aber BGB gilt"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss mein Chef das BGB beachten?', 2, '[{"text": "Ja", "correct": true, "because": "Grundlage für Arbeitsverträge"}, {"text": "Nein", "correct": false, "because": "Gesetzlich bindend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das BGB für meine Vergütung zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "BBiG regelt Azubi-Vergütung"}, {"text": "Ja", "correct": false, "because": "Nur allgemeine Regeln"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich wegen eines Vertragsbruchs nach BGB klagen?', 2, '[{"text": "Ja", "correct": true, "because": "Vertragsverletzung klagbar"}, {"text": "Nein", "correct": false, "because": "BGB bietet Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Gilt das BGB für Azubis?', 2, '[{"text": "Ja", "correct": true, "because": "Allgemeines Zivilrecht"}, {"text": "Nein", "correct": false, "because": "Azubis eingeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das BGB meine Arbeitszeit begrenzen?', 2, '[{"text": "Nein", "correct": true, "because": "ArbZG und JArbSchG zuständig"}, {"text": "Ja", "correct": false, "because": "Nur allgemeine Regeln"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das BGB für Kündigungen relevant?', 2, '[{"text": "Ja", "correct": true, "because": "Kündigungsfristen geregelt"}, {"text": "Nein", "correct": false, "because": "Zusammen mit KSchG"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss mein Ausbildungsvertrag schriftlich sein laut BGB?', 2, '[{"text": "Nein", "correct": true, "because": "Formfreiheit, aber BBiG fordert Schrift"}, {"text": "Ja", "correct": false, "because": "BGB verlangt es nicht direkt"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was regelt das BGB hauptsächlich für meinen Ausbildungsvertrag?', 2, '[{"text": "Vertragspflichten", "correct": true, "because": "Allgemeines Vertragsrecht"}, {"text": "Prüfungen", "correct": false, "because": "IHK-Aufgabe"}, {"text": "Urlaub", "correct": false, "because": "BUrlG"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin kündigt mich fristlos. Was sagt das BGB?', 3, '[{"text": "Nur bei wichtigem Grund", "correct": true, "because": "§626 BGB"}, {"text": "Immer erlaubt", "correct": false, "because": "Fristlos eingeschränkt"}, {"text": "Nie möglich", "correct": false, "because": "Ausnahmen erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kündigungsfrist gilt laut BGB für mich als Azubi?', 2, '[{"text": "4 Wochen", "correct": true, "because": "§622 BGB"}, {"text": "1 Tag", "correct": false, "because": "Zu kurz"}, {"text": "3 Monate", "correct": false, "because": "Zu lang"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, was das BGB für mich regelt. Was sage ich?', 3, '[{"text": "Vertragsregeln", "correct": true, "because": "Grundlage Ausbildungsvertrag"}, {"text": "Nur Arbeitszeit", "correct": false, "because": "ArbZG"}, {"text": "Nur Prüfungen", "correct": false, "because": "BBiG"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte meines Ausbildungsvertrags regelt das BGB?', 4, '[{"text": "Vertragsschluss", "correct": true, "because": "§§305 ff."}, {"text": "Kündigung", "correct": true, "because": "§§621 ff."}, {"text": "Pflichten", "correct": true, "because": "§§241 ff."}, {"text": "Arbeitszeit", "correct": false, "because": "ArbZG"}]'),
('00000000-0000-0000-0000-000000000000', 'Was kann ich nach BGB tun, wenn der Betrieb meinen Vertrag bricht?', 3, '[{"text": "Schadensersatz fordern", "correct": true, "because": "§249 BGB"}, {"text": "Vertrag erfüllen lassen", "correct": true, "because": "§281 BGB"}, {"text": "Klage einreichen", "correct": true, "because": "Rechtsweg"}, {"text": "Urlaub verlangen", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben Streit über meine Kündigung. Was sagt das BGB?', 3, '[{"text": "Frist von 4 Wochen", "correct": true, "because": "§622 BGB"}, {"text": "Schriftform möglich", "correct": true, "because": "§623 BGB"}, {"text": "Wichtiger Grund für Fristlosigkeit", "correct": true, "because": "§626 BGB"}, {"text": "Mündlich ausreichend", "correct": false, "because": "Schriftform nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten habe ich laut BGB als Azubi?', 4, '[{"text": "Vertrag einhalten", "correct": true, "because": "§241 BGB"}, {"text": "Treuepflicht", "correct": true, "because": "§242 BGB"}, {"text": "Arbeit leisten", "correct": true, "because": "§611a BGB"}, {"text": "Prüfungen ablegen", "correct": false, "because": "BBiG"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das BGB regelt meinen Vertragsschluss. b) Es bestimmt meine Arbeitszeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vertrag ja, Arbeitszeit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BGB erlaubt fristlose Kündigung bei Grund. b) Es regelt meinen Urlaub.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kündigung ja, Urlaub nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das BGB gilt für meinen Vertrag. b) Es ist nur für Erwachsene.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vertrag ja, alle betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BGB regelt Kündigungsfristen. b) Es schreibt meine Prüfungen vor.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fristen ja, Prüfungen nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

